class Solution:
    def diameterOfBinaryTree(self, root):
        best = 0
        def dfs(node):
            nonlocal best
            if not node: return 0
            left, right = dfs(node.left), dfs(node.right)
            best = max(best, left + right)
            return 1 + max(left, right)
        dfs(root)
        return best

